{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.sku_group_sample_to_live as ( with live_date_pre as ( select LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' IN REVERSE(value:sku::STRING))) AS sku_group, min(PUBLISHEDAT::date) as live_date, lower(status) as status from snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value group by 1,3 ), sku_count as ( select sku_group, count(*) as status_count from live_date_pre group by 1 ), live_date_main as ( select upper(trim(a.sku_group)) as sku_group, a.status, live_date, row_number() over (partition by a.sku_group order by a.live_date desc) as rn, b.status_count from live_date_pre a left join sku_count b on a.sku_group = b.sku_group ), live_date as ( select sku_group, status, live_date from live_date_main where (status_count > 1 and rn = 2) or (status_count = 1 and rn = 1) ), inwards as ( select sku_group, date, sum(inwared_quantity) as quant from snitch_db.maplemonk.Inwards where upper(sku_group) not like \'%MP-%\' group by 1,2 ), catalog as ( select replace(upper(trim(sku_group)),\'MP-\',\'\') as sku_group, \'not_in_shopify\' as status, min(date) as latest_inward_date, sum(quant) as units_on_hand from inwards where quant > 0 group by 1 ), sample_received_date as ( select distinct upper(trim(REVERSE(SUBSTRING(REVERSE(sku_group), CHARINDEX(\'-\', REVERSE(sku_group)) + 1, LEN(sku_group))))) AS sku_group, TO_CHAR(TRY_TO_DATE(sample_recieved_date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as sample_recieved_date from snitch_db.maplemonk.google_Sheet_sample_recieved ), PSLJ AS( SELECT replace((upper(trim(sku))),\'MP-\',\'\') as sku_group, a.\"Factory_\'\", a.OWNER as editor_owner, a.Photoshoot_Status, a.IMAGE_SELECTION, TO_CHAR(TRY_TO_DATE(a.Recevied_Date_, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as edit_received_date, TO_CHAR(TRY_TO_DATE(a.Completion_Date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as edit_completed_date, TO_CHAR(TRY_TO_DATE(a.final_shared_date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as catalogix_sent_timestamp, TO_CHAR(TRY_TO_DATE(a.final_recieved_date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as catalogix_received_timestamp, TO_CHAR(TRY_TO_DATE(a.live_on_shopify_date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as live_on_shopify_date, tags as wtw_tags, production_poc from snitch_db.maplemonk.gs_pslj a where upper(sku) not like \'%MP-%\' ), shoot_date as ( SELECT DISTINCT Upper (REGEXP_REPLACE(sku, \'-[^-]+$\', \'\')) AS sku_group, TO_CHAR(TRY_TO_DATE(date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS shoot_date FROM snitch_db.maplemonk.gs_shoot_date ), RTS AS ( SELECT replace(upper(trim(sku)),\'MP-\',\'\') as sku_group, CLASS, \'ready_to_dispatch\' as status, REPEAT, VENDOR, WAEHOUSE, DESCIPTON, TO_CHAR(TRY_TO_DATE(DELIVEY_DATE_, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as DELIVERY_DATE, online_qty, QC_STATUS, QC_REPORT FROM snitch_db.maplemonk.catalog_main where repeat = \'NO\' and (to_date(DELIVEY_DATE_, \'DD/MM/YYYY\') >= current_date - 3 or to_date(DELIVEY_DATE_, \'DD/MM/YYYY\') is null) and upper(trim(sku)) not in (select sku_group from catalog) and upper(sku) not like \'%MP-%\' ), inventory as ( select replace(upper(trim(sku_group)),\'MP-\',\'\') as sku_group, sellable_inventory as inventory from snitch_db.maplemonk.availability_master_v2 where upper(sku_group) not like \'%MP-%\' ), main_data as ( select coalesce(a.sku_group,c.SKU_GROUP,r.sku_group) as sku_group, sr.sample_recieved_date::date as sample_received_date, l.live_date::date as live_date, a.Photoshoot_Status, sd.shoot_date::date as shoot_date, a.edit_received_date, a.editor_owner, a.edit_completed_date, a.catalogix_sent_timestamp, a.catalogix_received_timestamp, a.production_poc, r.delivery_date, cast(greatest(coalesce(r.online_qty,0),coalesce(c.units_on_hand,0),coalesce(i.inventory,0)) as number) as units_on_hand, c.latest_inward_date as inward_date, case when a.sku_group is null and c.sku_group is not null then \'not_in_PSLJ\' else \'present_in_PSLJ\' end as pslj_status, coalesce(l.status,c.status,r.status) as status, DATEDIFF(day, sr.sample_recieved_date, l.live_date) AS sr_live_tat, DATEDIFF(day, sr.sample_recieved_date, sd.shoot_date) AS shoot_tat, datediff(day,sd.shoot_date,a.edit_received_date) as shootdone_editreceived_tat, datediff(day,a.edit_received_date,a.edit_completed_date) as edit_tat, datediff(day,a.edit_completed_date,a.catalogix_sent_timestamp) as editdone_catalogixsent_tat, datediff(day,a.catalogix_sent_timestamp,a.catalogix_received_timestamp) as catalogix_tat, datediff(day,a.catalogix_received_timestamp,l.live_date) as live_tat, a.wtw_tags FROM PSLJ a FULL OUTER JOIN catalog c ON a.sku_group = c.sku_group FULL OUTER JOIN RTS r ON COALESCE(a.sku_group, c.SKU_GROUP) = r.sku_group FULL OUTER JOIN live_date l ON COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = l.sku_group left join inventory i on COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = i.sku_group left join sample_received_date sr on COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = sr.sku_group left join shoot_date sd on COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = sd.sku_group ), main_data2 as ( select *, CASE when lower(status) = \'active\' or live_date is not null then \'NO_ISSUES\' when lower(status) = \'draft\' and inward_date is not null then \'QC\' when lower(status) = \'draft\' and inward_date is null then \'INWARD_NOT_DONE\' when lower(status) = \'ready_to_dispatch\' and shoot_date is null and sample_received_date is not null then \'RTS_SHOOT_NOT_DONE\' when lower(status) = \'ready_to_dispatch\' and shoot_date is not null and EDIT_RECEIVED_DATE is null then \'RTS_EDIT_NOT_DONE\' when lower(status) = \'ready_to_dispatch\' and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and (catalogix_received_timestamp is null or CATALOGIX_SENT_TIMESTAMP is null) then \'RTS_CATALOGIX_NOT_DONE\' when lower(status) = \'ready_to_dispatch\' and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and CATALOGIX_SENT_TIMESTAMP is not null and catalogix_received_timestamp is not null and inward_date is null then \'RTS_INWARD_NOT_DONE\' when lower(status) = \'ready_to_dispatch\' and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and CATALOGIX_SENT_TIMESTAMP is not null and catalogix_received_timestamp is not null and inward_date is not null then \'RTS_QC\' when lower(status) not in (\'active\',\'draft\') and sample_received_date is null and shoot_date is null then \'SAMPLE_NOT_RECEIVED\' when lower(status) not in (\'ready_to_dispatch\',\'active\',\'draft\') and sample_received_date is not null and shoot_date is null then \'SHOOT_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'active\',\'draft\') and shoot_date is not null and (edit_completed_date is null or EDIT_RECEIVED_DATE is null) then \'EDIT_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'active\',\'draft\') and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and (catalogix_received_timestamp is null or CATALOGIX_SENT_TIMESTAMP is null) then \'CATALOGIX_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'active\',\'draft\') and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and catalogix_received_timestamp is not null and CATALOGIX_SENT_TIMESTAMP is not null and inward_date is null then \'INWARD_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'active\',\'draft\') and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and catalogix_received_timestamp is not null and CATALOGIX_SENT_TIMESTAMP is not null and inward_date is not null then \'QC\' else \'others\' end as final_status from main_data ), metafields_pre as ( select SKU_GROUP, SAMPLE_RECEIVED_DATE, LIVE_DATE, PHOTOSHOOT_STATUS, SHOOT_DATE, EDITOR_OWNER, DELIVERY_DATE, UNITS_ON_HAND, INWARD_DATE, PSLJ_STATUS, STATUS, SR_LIVE_TAT SHOOT_TAT, SHOOTDONE_EDITRECEIVED_TAT, EDIT_TAT, EDITDONE_CATALOGIXSENT_TAT, CATALOGIX_TAT, LIVE_TAT, FINAL_STATUS,wtw_tags, production_poc, to_date(edit_received_date,\'YYYY-MM-DD\') as edit_received_date, to_date(EDIT_COMPLETED_DATE,\'YYYY-MM-DD\') as EDIT_COMPLETED_DATE, to_date(CATALOGIX_SENT_TIMESTAMP,\'YYYY-MM-DD\') as CATALOGIX_SENT_TIMESTAMP, to_date(CATALOGIX_RECEIVED_TIMESTAMP,\'YYYY-MM-DD\') as CATALOGIX_RECEIVED_TIMESTAMP, from main_data2 ), sample_shoot_tracker as ( select upper(trim(sku_group)) as sku_group, TO_CHAR(TRY_TO_DATE(sample_shoot, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as sample_shoot, TO_CHAR(TRY_TO_DATE(SAMPLE_RECIEVED_DATE, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as SAMPLE_RECIEVED_DATE_to_shot, TO_CHAR(TRY_TO_DATE(SAMPLE_RETURNED_DATE, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as sample_returned_date_to_shoot, TO_CHAR(TRY_TO_DATE(SAMPLE_OUT_FOR_SHOOT_DATE, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as SAMPLE_OUT_FOR_SHOOT_DATE from snitch_db.maplemonk.shoot_sample_tracker_Sheet1 ) select a.*, occassion_new, occassion, print_design, collar, product_tags, material_new, material, rise, pocket, sleeve_type, fit, color, closure, length, vendor, designs, style, sample_shoot, SAMPLE_RECIEVED_DATE_to_shot, sample_returned_date_to_shoot, SAMPLE_OUT_FOR_SHOOT_DATE from metafields_pre a left join snitch_db.maplemonk.metafields_data b on a.sku_group = b.sku_group left join sample_shoot_tracker c on a.sku_group = c.sku_group where a.sku_group not in (\'4MSFR0918\',\'4MSK8662-01\',\'4MSK8662-02\',\'4MSK8662-03\',\'4MSK8662-04\',\'4MSN1310-08\',\'4MSN1310-05\',\'4MSN1310-02\',\'4MST0218-03-T-SHIRT\',\'4MST0226-01-T-SHIRT\',\'4MTR0123-02\',\'4MTR0123-04\',\'4MSN1345-11-SHIRT\',\'4MSN1310-01-SHIRT\',\'4MSN1345-10-SHIRT\',\'4MSN1310-04-SHIRT\',\'4MSN1345-06-SHIRT\',\'4MSN1345-05-SHIRT\',\'4MSN1310-09-SHIRT\',\'4MSN1310-03-SHIRT\',\'4MSO3690-02\',\'4MTP0025-04\',\'4MSN1075-07-SHIRT\',\'4MST0224-01-T-SHIRT\',\'4MSN1310-10-SHIRT\',\'4MSS2142-16\',\'4MSS2142-11\',\'4MSS2648-5\',\'4MSS1813-25\',\'4MSS1813-24\',\'4MSS1813-16\',\'4MSS1813-17\',\'4MSS1813-11\',\'4MSS1813-26\',\'4MSS1813-12\',\'4MST2066-02\',\'4MSS3166-02\',\'4MSR5053-03\',\'4MSS1813-21\',\'4MSFR0929_T\',\'4MSFR0928_T\',\'4MSFR0927_T\',\'4MSFR0925_T\',\'4MSFR0926_T\') ) ;",
                    "transaction": true
